graphQueries.baseQuery:
{{graphQueriesTableName}}
| where SourceSystem == "Feedly"
| summarize count() by bin(TimeGenerated, 1h)

sampleQueries.query:
{{graphQueriesTableName}}
| where SourceSystem == "Feedly"
| sort by TimeGenerated desc

{{graphQueriesTableName}}
| where SourceSystem == "Feedly" and ObservableKey == "ipv4-addr:value"
| sort by TimeGenerated desc

{{graphQueriesTableName}}
| where SourceSystem == "Feedly" and ObservableKey == "domain-name:value"
| sort by TimeGenerated desc

{{graphQueriesTableName}}
| where SourceSystem == "Feedly" and ObservableKey == "url:value"
| sort by TimeGenerated desc
